package org.runerealm.server.app

import com.github.michaelbull.logging.InlineLogger
import io.netty.buffer.Unpooled
import java.nio.file.Path
import kotlin.io.path.isDirectory
import kotlin.io.path.listDirectoryEntries
import org.openrs2.cache.Cache

/**
 * Packs the RuneRealm login screen into the client (js5) cache: the background `title.jpg` and the
 * `logo` sprite, which carries the right half of the background so it is not mirrored. The assets
 * are generated by `Branding Resources/build_client_branding.py`.
 */
internal object ClientBranding {
    private val logger = InlineLogger()

    private const val BINARY_ARCHIVE = 10
    private const val SPRITE_ARCHIVE = 8

    /**
     * Opens the js5 cache at [js5CachePath], packs the assets when they differ, and closes it
     * again. The cache must not stay open: the type updater deletes and re-copies the js5 cache
     * directory, which fails (leaving a mix of old and new files) while file handles are held,
     * notably on Windows.
     */
    fun apply(js5CachePath: Path) {
        if (!js5CachePath.isDirectory() || js5CachePath.listDirectoryEntries().isEmpty()) {
            return
        }
        Cache.open(js5CachePath).use { cache ->
            val updated =
                write(cache, BINARY_ARCHIVE, "title.jpg", resource("title.jpg")) or
                    write(cache, SPRITE_ARCHIVE, "logo", resource("logo.dat"))
            if (updated) {
                logger.info { "Packed RuneRealm login screen into the client cache." }
            }
            val renamed = renameText(cache, TEXT_ARCHIVES)
            if (renamed > 0) {
                logger.info { "Renamed RuneScape to RuneRealm in $renamed client cache files." }
            }
        }
        // A separate session: openrs2 refuses to read a group back (version mismatch) after it was
        // written earlier in the same session, and the rename above rewrites interface groups.
        Cache.open(js5CachePath).use { cache ->
            val overridden = ClientTextOverrides.apply(cache)
            if (overridden > 0) {
                logger.info { "Rebranded bank titles in $overridden client cache files." }
            }
        }
    }

    private fun write(cache: Cache, archive: Int, group: String, bytes: ByteArray): Boolean {
        val current =
            if (cache.exists(archive, group)) {
                cache.read(archive, group, 0).use { buf ->
                    ByteArray(buf.readableBytes()).also(buf::readBytes)
                }
            } else {
                null
            }
        if (current != null && current.contentEquals(bytes)) {
            return false
        }
        cache.write(archive, group, 0, Unpooled.wrappedBuffer(bytes))
        return true
    }

    /**
     * Replaces the display name "RuneScape" (and "RUNESCAPE") in [archive]'s files with
     * "RuneRealm". Both names are 9 characters, so strings keep their length and the surrounding
     * binary data (string terminators, offsets) stays valid. URLs (`oldschool.runescape.wiki`) and
     * identifiers (`mtol_whistle_runescape`) are left alone so wiki lookups and links still work.
     */
    private fun renameText(cache: Cache, archives: IntArray): Int {
        // Read everything before writing anything: once openrs2 rewrites a group, reading files
        // from it again in the same session fails with a version mismatch.
        val changes = mutableListOf<Triple<Int, Int, Pair<Int, ByteArray>>>()
        for (archive in archives) {
            if (!cache.exists(archive)) {
                continue
            }
            for (group in cache.list(archive).asSequence().toList()) {
                for (file in cache.list(archive, group.id).asSequence().toList()) {
                    val bytes =
                        cache.read(archive, group.id, file.id).use { buf ->
                            ByteArray(buf.readableBytes()).also(buf::readBytes)
                        }
                    if (renameRuneScape(bytes)) {
                        changes += Triple(archive, group.id, file.id to bytes)
                    }
                }
            }
        }
        for ((archive, group, file) in changes) {
            cache.write(archive, group, file.first, Unpooled.wrappedBuffer(file.second))
        }
        return changes.size
    }

    /** Rewrites [bytes] in place, returning `true` if anything changed. */
    internal fun renameRuneScape(bytes: ByteArray): Boolean {
        var changed = false
        for ((old, new) in RENAMES) {
            var i = 0
            while (i <= bytes.size - old.size) {
                if (bytes.matchesWord(old, i)) {
                    new.copyInto(bytes, i)
                    changed = true
                    i += old.size
                } else {
                    i++
                }
            }
        }
        return changed
    }

    private fun ByteArray.matchesWord(word: ByteArray, offset: Int): Boolean {
        for (j in word.indices) {
            if (this[offset + j] != word[j]) {
                return false
            }
        }
        val before = getOrNull(offset - 1)?.toInt()?.toChar()
        val after = getOrNull(offset + word.size)?.toInt()?.toChar()
        return !before.isNamePart() && !after.isNamePart()
    }

    private fun Char?.isNamePart(): Boolean =
        this != null && (isLetterOrDigit() || this == '_' || this == '.' || this == '/')

    private val RENAMES =
        listOf(
            "RuneScape".toByteArray() to "RuneRealm".toByteArray(),
            "RUNESCAPE".toByteArray() to "RUNEREALM".toByteArray(),
        )

    /** Config (names, enums, db rows), interface and client script archives. */
    private val TEXT_ARCHIVES = intArrayOf(2, 3, 12)

    private fun resource(name: String): ByteArray {
        val stream =
            ClientBranding::class.java.getResourceAsStream("branding/$name")
                ?: error("Missing branding resource: $name")
        return stream.use { it.readBytes() }
    }
}

private inline fun <T> io.netty.buffer.ByteBuf.use(block: (io.netty.buffer.ByteBuf) -> T): T =
    try {
        block(this)
    } finally {
        release()
    }
